{
  "units": [
    {
      "quote": "A limited-validity passport using endorsement 46 should be issued when the medical circumstance that requires eyeglasses is temporary and the applicant has urgent or emergency travel.",
      "scope_quotes": [],
      "kind": "recommendation",
      "meaning": "A limited-validity passport using endorsement 46 should be issued under the joint conditions that the medical circumstance requiring eyeglasses is temporary and the applicant has urgent or emergency travel."
    },
    {
      "quote": "The applicant’s expression should be natural.",
      "scope_quotes": [],
      "kind": "recommendation",
      "meaning": "The applicant's facial expression in the photograph should be natural."
    },
    {
      "quote": "Normal, unexaggerated smiles are acceptable, but unusual expressions and squinting are not.",
      "scope_quotes": [],
      "kind": "permission",
      "meaning": "Normal and unexaggerated smiles are permitted in the photograph, whereas unusual expressions and squinting are prohibited."
    },
    {
      "quote": "Applicants with physical or mental disabilities, including loss of muscle control (e.g., age-related degeneration or because of a medical condition such as Bell's Palsy), may not be able to produce a natural or unexaggerated expression.",
      "scope_quotes": [],
      "kind": "statement",
      "meaning": "Applicants who have physical or mental disabilities—including loss of muscle control resulting from age-related degeneration or medical conditions like Bell's Palsy—may be unable to present a natural or unexaggerated facial expression."
    },
    {
      "quote": "You may accept a photograph without a natural or unexaggerated expression in these circumstances.",
      "scope_quotes": [
        "Applicants with physical or mental disabilities, including loss of muscle control (e.g., age-related degeneration or because of a medical condition such as Bell's Palsy), may not be able to produce a natural or unexaggerated expression."
      ],
      "kind": "permission",
      "meaning": "Personnel are permitted to accept a photograph lacking a natural or unexaggerated expression when the applicant has a physical or mental disability (such as loss of muscle control from age-related degeneration or a medical condition)."
    },
    {
      "quote": "Both of the applicant’s eyes should also be visible and open in the photograph (see the exception for infants in 8 FAM 402.1-1).",
      "scope_quotes": [],
      "kind": "recommendation",
      "meaning": "Both eyes of the applicant should be open and visible in the photograph, subject to the referenced exception for infants in 8 FAM 402.1-1."
    },
    {
      "quote": "If the applicant is unable to open one or both eyes because of a medical condition, you may accept the photograph.",
      "scope_quotes": [],
      "kind": "permission",
      "meaning": "Personnel are permitted to accept the photograph if the applicant cannot open one eye or both eyes due to a medical condition."
    },
    {
      "quote": "In rare cases, if it is unlikely that the closed eye(s) or exaggerated expression are because of a medical condition, you should request a medical statement signed by a medical professional/health practitioner.",
      "scope_quotes": [],
      "kind": "recommendation",
      "meaning": "In rare cases where it is unlikely that closed eye(s) or an exaggerated expression stem from a medical condition, personnel should request a signed medical statement from a medical professional or health practitioner."
    },
    {
      "quote": "Processing and communications/customer service personnel at passport agencies/centers or consular section personnel should refer applications without photographs to their supervisor for guidance on processing passport applications received without photographs;",
      "scope_quotes": [
        "Applications received without photographs:"
      ],
      "kind": "recommendation",
      "meaning": "When applications are received without photographs, processing personnel, communications/customer service personnel at passport agencies/centers, or consular section personnel should refer them to their supervisor for guidance on handling."
    },
    {
      "quote": "You must not accept a form DS-11 or form DS-82 received without a photograph at the public counter.",
      "scope_quotes": [
        "Applications received without photographs:"
      ],
      "kind": "prohibition",
      "meaning": "Personnel are strictly prohibited from accepting a Form DS-11 or Form DS-82 at the public counter if it is received without a photograph."
    },
    {
      "quote": "See 8 FAM 1001.2 regarding importing photographs for forms DS-5504;",
      "scope_quotes": [
        "Applications received without photographs:"
      ],
      "kind": "background",
      "meaning": "Cross-reference pointing to 8 FAM 1001.2 for guidance on importing photographs for Form DS-5504, carrying no independent substantive rule in this passage."
    },
    {
      "quote": "Passport specialists must suspend a form DS-11 received without a photograph from an acceptance facility.",
      "scope_quotes": [
        "Applications received without photographs:"
      ],
      "kind": "requirement",
      "meaning": "Passport specialists are required to suspend any Form DS-11 that is received from an acceptance facility without a photograph."
    },
    {
      "quote": "The applicant must re-execute the form DS-11 (see IRL 975-04); and",
      "scope_quotes": [
        "Applications received without photographs:",
        "Passport specialists must suspend a form DS-11 received without a photograph from an acceptance facility."
      ],
      "kind": "requirement",
      "meaning": "When a Form DS-11 is suspended because it was received from an acceptance facility without a photograph, the applicant is required to re-execute the Form DS-11."
    },
    {
      "quote": "Passport specialists must suspend a form DS-82 or form DS-5504 received without a photograph (see IRL 1000-05 and IRL 1018-14).",
      "scope_quotes": [
        "Applications received without photographs:"
      ],
      "kind": "requirement",
      "meaning": "Passport specialists are required to suspend any Form DS-82 or Form DS-5504 that is received without an accompanying photograph."
    }
  ]
}
